import java.util.Scanner;import calc.basic.BasicCalc;import calc.advanced.AdvancedCalc;import print.display.Display;
public class Program10 {public static void main(String[] args){Scanner sc=new Scanner(System.in);BasicCalc basic=new BasicCalc();AdvancedCalc advanced=new AdvancedCalc();Display display=new Display();int choice;do{System.out.println("\n--- Scientific Calculator ---\n1. Add\n2. Subtract\n3. Multiply\n4. Divide\n5. Power\n6. Square Root\n7. Log\n8. Exit");System.out.print("Enter choice: ");choice=sc.nextInt();double a,b;switch(choice){case 1:System.out.print("Enter two numbers: ");a=sc.nextDouble();b=sc.nextDouble();display.showResult(basic.add(a,b));break;case 2:System.out.print("Enter two numbers: ");a=sc.nextDouble();b=sc.nextDouble();display.showResult(basic.subtract(a,b));break;case 3:System.out.print("Enter two numbers: ");a=sc.nextDouble();b=sc.nextDouble();display.showResult(basic.multiply(a,b));break;case 4:System.out.print("Enter two numbers: ");a=sc.nextDouble();b=sc.nextDouble();display.showResult(basic.divide(a,b));break;case 5:System.out.print("Enter base and exponent: ");a=sc.nextDouble();b=sc.nextDouble();display.showResult(advanced.power(a,b));break;case 6:System.out.print("Enter number: ");display.showResult(advanced.sqrt(sc.nextDouble()));break;case 7:System.out.print("Enter number: ");display.showResult(advanced.log(sc.nextDouble()));break;case 8:System.out.println("Exiting...");break;default:System.out.println("Invalid choice");}}while(choice!=8);sc.close();}}
